# FILE: Chart.yaml
apiVersion: v2
name: postgres-nonprod
description: A Helm chart for deploying a PostgreSQL database in a non-production environment
type: application
version: 0.1.0
appVersion: "16.2"
---
# FILE: values.yaml
# Default values for postgres-nonprod.
# This is a YAML-formatted file.
# Declare variables to be passed into your templates.

replicaCount: 1

image:
  repository: postgres
  tag: "16.2"
  pullPolicy: IfNotPresent

nameOverride: ""
fullnameOverride: ""

service:
  type: ClusterIP
  port: 5432

persistence:
  enabled: true
  size: 10Gi
  storageClass: ""
  accessMode: ReadWriteOnce

resources:
  limits:
    cpu: 500m
    memory: 512Mi
  requests:
    cpu: 250m
    memory: 256Mi

nodeSelector: {}

tolerations: []

affinity: {}

# PostgreSQL configuration
postgresql:
  database: appdb
  username: appuser
  # Password will be auto-generated if not set
  password: ""
  # Existing secret name (if password is managed externally)
  existingSecret: ""
  postgresPassword: ""
  initdbArgs: ""
  extraEnvVars: []
  extraEnvVarsCM: ""
  extraEnvVarsSecret: ""

# Init job configuration
initJob:
  enabled: true
  backoffLimit: 5
  activeDeadlineSeconds: 300
  resources:
    limits:
      cpu: 200m
      memory: 256Mi
    requests:
      cpu: 100m
      memory: 128Mi

# Security context
securityContext:
  enabled: true
  fsGroup: 999
  runAsUser: 999
  runAsNonRoot: true

# Network policy
networkPolicy:
  enabled: false
  ingress:
    - from:
        - podSelector:
            matchLabels:
              app.kubernetes.io/name: postgres-nonprod
---
# FILE: templates/_helpers.tpl
{{- define "postgres-nonprod.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "postgres-nonprod.fullname" -}}
{{- if .Values.fullnameOverride }}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- $name := default .Chart.Name .Values.nameOverride }}
{{- if contains $name .Release.Name }}
{{- .Release.Name | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" }}
{{- end }}
{{- end }}
{{- end }}

{{- define "postgres-nonprod.chart" -}}
{{- printf "%s-%s" .Chart.Name .Chart.Version | replace "+" "_" | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "postgres-nonprod.labels" -}}
helm.sh/chart: {{ include "postgres-nonprod.chart" . }}
{{ include "postgres-nonprod.selectorLabels" . }}
{{- if .Chart.AppVersion }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
{{- end }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- end }}

{{- define "postgres-nonprod.selectorLabels" -}}
app.kubernetes.io/name: {{ include "postgres-nonprod.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end }}

{{- define "postgres-nonprod.serviceAccountName" -}}
{{- default (include "postgres-nonprod.fullname" .) .Values.serviceAccount.name }}
{{- end }}

{{- define "postgres-nonprod.secretName" -}}
{{- if .Values.postgresql.existingSecret }}
{{- .Values.postgresql.existingSecret }}
{{- else }}
{{- include "postgres-nonprod.fullname" . }}
{{- end }}
{{- end }}
---
# FILE: templates/secret.yaml
apiVersion: v1
kind: Secret
metadata:
  name: {{ include "postgres-nonprod.secretName" . }}
  labels:
    {{- include "postgres-nonprod.labels" . | nindent 4 }}
type: Opaque
data:
  {{- if not .Values.postgresql.existingSecret }}
  postgres-password: {{ .Values.postgresql.postgresPassword | default (randAlphaNum 32) | b64enc | quote }}
  password: {{ .Values.postgresql.password | default (randAlphaNum 32) | b64enc | quote }}
  {{- end }}
  database: {{ .Values.postgresql.database | b64enc | quote }}
  username: {{ .Values.postgresql.username | b64enc | quote }}
---
# FILE: templates/service.yaml
apiVersion: v1
kind: Service
metadata:
  name: {{ include "postgres-nonprod.fullname" . }}-headless
  labels:
    {{- include "postgres-nonprod.labels" . | nindent 4 }}
  annotations:
    service.alpha.kubernetes.io/tolerate-unready-endpoints: "true"
spec:
  clusterIP: None
  ports:
    - port: {{ .Values.service.port }}
      targetPort: postgres
      protocol: TCP
      name: postgres
  selector:
    {{- include "postgres-nonprod.selectorLabels" . | nindent 4 }}
---
# FILE: templates/statefulset.yaml
apiVersion: apps/v1
kind: StatefulSet
metadata:
  name: {{ include "postgres-nonprod.fullname" . }}
  labels:
    {{- include "postgres-nonprod.labels" . | nindent 4 }}
spec:
  serviceName: {{ include "postgres-nonprod.fullname" . }}-headless
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      {{- include "postgres-nonprod.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      labels:
        {{- include "postgres-nonprod.selectorLabels" . | nindent 8 }}
    spec:
      {{- if .Values.securityContext.enabled }}
      securityContext:
        fsGroup: {{ .Values.securityContext.fsGroup }}
        runAsUser: {{ .Values.securityContext.runAsUser }}
        runAsNonRoot: {{ .Values.securityContext.runAsNonRoot }}
      {{- end }}
      containers:
        - name: postgres
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          ports:
            - containerPort: 5432
              name: postgres
          env:
            - name: POSTGRES_USER
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres-nonprod.secretName" . }}
                  key: username
            - name: POSTGRES_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres-nonprod.secretName" . }}
                  key: password
            - name: POSTGRES_DB
              valueFrom:
                secretKeyRef:
                  name: {{ include "postgres-nonprod.secretName" . }}
                  key: database
            - name: PGDATA
              value: /var/lib/postgresql/data/pgdata
            {{- if .Values.postgresql.initdbArgs }}
            - name: POSTGRES_INITDB_ARGS
              value: {{ .Values.postgresql.initdbArgs }}
            {{- end }}
            {{- if .Values.postgresql.extraEnvVars }}
            {{- toYaml .Values.postgresql.extraEnvVars | nindent 12 }}
            {{- end }}
          {{- if or .Values.postgresql.extraEnvVarsCM .Values.postgresql.extraEnvVarsSecret }}
          envFrom:
            {{- if .Values.postgresql.extraEnvVarsCM }}
            - configMapRef:
                name: {{ .Values.postgresql.extraEnvVarsCM }}
            {{- end }}
            {{- if .Values.postgresql.extraEnvVarsSecret }}
            - secretRef:
                name: {{ .Values.postgresql.extraEnvVarsSecret }}
            {{- end }}
          {{- end }}
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
          volumeMounts:
            - name: data
              mountPath: /var/lib/postgresql/data
              subPath: pgdata
          livenessProbe:
            exec:
              command:
                - pg_isready
                - -U
                - {{ .Values.postgresql.username }}
